MERGE INTO HACKATHONS h USING (SELECT o.id opportunity_id, 'online' event_mode, SYSTIMESTAMP + INTERVAL '22' DAY start_date, SYSTIMESTAMP + INTERVAL '23' DAY end_date, 'Online' location, 4 team_size FROM OPPORTUNITIES o WHERE o.title='Campus Fintech Challenge') s ON (h.opportunity_id=s.opportunity_id) WHEN NOT MATCHED THEN INSERT (opportunity_id,event_mode,start_date,end_date,location,team_size) VALUES (s.opportunity_id,s.event_mode,s.start_date,s.end_date,s.location,s.team_size);
-- @statement
MERGE INTO HACKATHONS h USING (SELECT o.id opportunity_id, 'hybrid' event_mode, SYSTIMESTAMP + INTERVAL '52' DAY start_date, SYSTIMESTAMP + INTERVAL '53' DAY end_date, 'Campus and online' location, 5 team_size FROM OPPORTUNITIES o WHERE o.title='Smart Campus Buildathon') s ON (h.opportunity_id=s.opportunity_id) WHEN NOT MATCHED THEN INSERT (opportunity_id,event_mode,start_date,end_date,location,team_size) VALUES (s.opportunity_id,s.event_mode,s.start_date,s.end_date,s.location,s.team_size);
