MERGE INTO APPLICATIONS a USING (SELECT st.id student_id,o.id opportunity_id,'selected' status FROM STUDENTS st CROSS JOIN OPPORTUNITIES o WHERE st.roll_number='BL.EN.U4EAC24011' AND o.title='Graduate Software Engineer') s ON (a.student_id=s.student_id AND a.opportunity_id=s.opportunity_id) WHEN NOT MATCHED THEN INSERT (student_id,opportunity_id,status) VALUES (s.student_id,s.opportunity_id,s.status);
