MERGE INTO PLACEMENTS p USING (SELECT a.id application_id,o.role,o.description,o.ctc,o.location,o.employment_type,TRUNC(SYSDATE)-3 offer_date,o.min_cgpa,o.max_backlogs,o.eligible_departments_json,o.required_skills_json FROM APPLICATIONS a JOIN STUDENTS st ON st.id=a.student_id JOIN OPPORTUNITIES o ON o.id=a.opportunity_id WHERE st.roll_number='BL.EN.U4EAC24011' AND o.title='Graduate Software Engineer' AND a.status='selected') s ON (p.application_id=s.application_id) WHEN NOT MATCHED THEN INSERT (application_id,role,description,ctc,location,employment_type,offer_date,min_cgpa,max_backlogs,eligible_departments_json,required_skills_json) VALUES (s.application_id,s.role,s.description,s.ctc,s.location,s.employment_type,s.offer_date,s.min_cgpa,s.max_backlogs,s.eligible_departments_json,s.required_skills_json);
-- @statement
MERGE INTO INTERNSHIPS i USING (SELECT a.id application_id,o.role,TRUNC(SYSDATE)-70 start_date,TRUNC(SYSDATE)-10 end_date,1 ppo_converted FROM APPLICATIONS a JOIN STUDENTS st ON st.id=a.student_id JOIN OPPORTUNITIES o ON o.id=a.opportunity_id WHERE st.roll_number='BL.EN.U4EAC24014' AND o.title='Risk Technology Intern' AND a.status='selected') s ON (i.application_id=s.application_id) WHEN NOT MATCHED THEN INSERT (application_id,role,start_date,end_date,ppo_converted) VALUES (s.application_id,s.role,s.start_date,s.end_date,s.ppo_converted);
-- @statement
MERGE INTO HACKATHON_REGISTRATIONS r USING (SELECT h.id hackathon_id,st.id student_id,'Circuit Breakers' team_name FROM HACKATHONS h JOIN OPPORTUNITIES o ON o.id=h.opportunity_id CROSS JOIN STUDENTS st WHERE o.title='Campus Fintech Challenge' AND st.roll_number='BL.EN.U4EAC24011') s ON (r.hackathon_id=s.hackathon_id AND r.student_id=s.student_id) WHEN NOT MATCHED THEN INSERT (hackathon_id,student_id,team_name) VALUES (s.hackathon_id,s.student_id,s.team_name);
-- @statement
MERGE INTO HACKATHON_REGISTRATIONS r USING (SELECT h.id hackathon_id,st.id student_id,'Signal Crew' team_name FROM HACKATHONS h JOIN OPPORTUNITIES o ON o.id=h.opportunity_id CROSS JOIN STUDENTS st WHERE o.title='Campus Fintech Challenge' AND st.roll_number='BL.EN.U4EAC24012') s ON (r.hackathon_id=s.hackathon_id AND r.student_id=s.student_id) WHEN NOT MATCHED THEN INSERT (hackathon_id,student_id,team_name) VALUES (s.hackathon_id,s.student_id,s.team_name);
