MERGE INTO CERTIFICATES c USING (SELECT st.id student_id,'Foundations of Cloud Computing' certificate_name,'Open Learning Institute' issuer,DATE '2026-05-15' completion_date,'DEMO-CLOUD-001' credential_id,'/api/uploads/sample-certificate-cloud' certificate_url FROM STUDENTS st WHERE st.roll_number='BL.EN.U4EAC24011') s ON (c.student_id=s.student_id AND c.credential_id=s.credential_id) WHEN NOT MATCHED THEN INSERT (student_id,certificate_name,issuer,completion_date,credential_id,certificate_url) VALUES (s.student_id,s.certificate_name,s.issuer,s.completion_date,s.credential_id,s.certificate_url);
